import sys

def main():
    s = sys.stdin.readline().strip()
    line2 = sys.stdin.readline().strip()
    if not line2:
        return
    n = int(line2)

    MOD = 10007
    m = len(s)

    dp = [[0] * (n + 1) for _ in range(m)]

    for i in range(m):
        dp[i][0] = 1

    for j in range(1, n + 1):
        for i in range(m):
            ways = 0
            if s[i] == s[m - 1 - i]:
                if i + 1 < m - 1 - i:
                    if j >= 1:
                        ways = (ways + dp[i + 1][j - 1]) % MOD
                else:
                    ways = 1
            else:
                if j >= 1:
                    ways = (ways + dp[i + 1][j - 1] * 26) % MOD
                    ways = (ways + dp[i][j - 1] * 26) % MOD
                    if i + 1 < m - 1 - i:
                        ways = (ways - dp[i + 1][j - 1] * 26 * 26) % MOD
            dp[i][j] = ways % MOD

    ans = 0
    if m % 2 == 1:
        mid = m // 2
        if n % 2 == 0:
            ans = (dp[mid][n // 2] * 26 ** (n // 2)) % MOD
        else:
            ans = (dp[mid][n // 2] * n // 2 + 1) % MOD
    else:
        mid = m // 2 - 1
        if n % 2 == 0:
            ans = dp[mid][n // 2]
        else:
            ans = (dp[mid][n // ] * 26) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()
